import{_ as i,l,o as e,c as d,v as t,p as D,x as o,d as s,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"FDTD 掩模仿真","description":"","frontmatter":{"title":"FDTD 掩模仿真","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fdtd-mask.md","filePath":"litho/fdtd-mask.md","lastUpdated":1789023840000}'),p={name:"litho/fdtd-mask.md"};function E(A,a,c,T,f,m){const r=l("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="fdtd-掩模仿真" tabindex="-1">FDTD 掩模仿真 <a class="header-anchor" href="#fdtd-掩模仿真" aria-label="Permalink to &quot;FDTD 掩模仿真&quot;">​</a></h1><div class="epigraph"><p>掩模开口的电磁不是薄屏基尔霍夫：时域有限差分把吸收体当真实 3D 散射体来步进麦克斯韦方程。</p><footer>—— 对照 Yee 网格 FDTD（Taflove 传统）在掩模近场中的应用</footer></div><p><a href="/litho/mask-cost-cycle">上一课</a>收完掩模厂的钱与周期。缺口是：为什么 MPC 与 AIMS 必须存在——开口里的场不是设计多边形的投影。本课起仿真门，钉 FDTD 掩模仿真。周期结构的频域另一条路，留给[下一课](/litho/rcwa）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>晶圆 OPC 的紧凑核假定掩模近场可从透过率图快速得到。<a href="/litho/mask-3d-effect">掩模 3D</a> 已经声明厚吸收体、斜入射、侧壁让这个假定裂开。FDTD（finite-difference time-domain）在 Yee 网格上对 \\(E\\)、\\(H\\) 交错步进，自然含色散、吸收、斜入射（经宽带或斜波技术），适合孤立缺陷、修复补丁、非周期拐角。代价是体积网格：纳米级吸收体 + 若干波长的空气/多层，内存与时间把全芯片排除在外。</p><p>缺口是<strong>近场真解的一种算法</strong>，不是再讲一次成像 TCC。把 FDTD 当全芯片 OPC 引擎，量级错了。</p><h3 id="与薄屏的差在哪用" tabindex="-1">与薄屏的差在哪用 <a class="header-anchor" href="#与薄屏的差在哪用" aria-label="Permalink to &quot;与薄屏的差在哪用&quot;">​</a></h3><p>薄屏足够时，FDTD 只浪费。差出现在：EUV 吸收体厚度与波长同量级、DUV attPSM 边、高 NA 大角度、缺陷体积。校准紧凑 3D 模型需要 FDTD（或 RCWA）当老师，而不是当每步前向。</p><p><span class="marginnote">网格要解析趋肤深度与尖角。欠采样会假装侧壁不重要。收敛研究属于方法，不是可选项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>域：吸收体剖面（来自 <a href="/litho/mask-etch-sidewall">侧壁课</a>）+ 多层（EUV）+ PML 吸收边界。激励：扫描机照明方向的平面波集合，再按光源积分。输出：掩模近场或等效薄屏修正，交给远场成像。与 AIMS 对照验证材料光学常数是否用对。</p><p>用途分层：热区与缺陷用 FDTD；周期线栅用下一课 RCWA 更便宜。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Yee 算法是麦克斯韦的中心差分，数值色散与稳定条件（CFL）限制时间步。金属与高 k 材料要用色散模型（Debye/Drude 一类），否则能量不守恒、相位边错。近场含倏逝分量，传播到晶圆瞳后被 NA 截断——所以 FDTD 的价值是把通带内那部分算对，不是把近场每一个纳米细节都印到硅上。</p>',14)),(e(),D(h,null,{default:o(()=>[n(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROF%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%203D%20%E5%89%96%E9%9D%A2%22%5D%20--%3E%20FDTD%5B%22Yee%20FDTD%20%E8%BF%91%E5%9C%BA%22%5D%0A%20%20ILL%5B%22%E7%85%A7%E6%98%8E%E5%B9%B3%E9%9D%A2%E6%B3%A2%22%5D%20--%3E%20FDTD%0A%20%20FDTD%20--%3E%20NF%5B%22%E6%8E%A9%E6%A8%A1%E8%BF%91%E5%9C%BA%22%5D%0A%20%20NF%20--%3E%20FAR%5B%22%E7%9E%B3%E6%BB%A4%E6%B3%A2%20%2B%20%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%0A%20%20FAR%20--%3E%20CAL%5B%22%E6%A0%A1%E5%87%86%E7%B4%A7%E5%87%91%203D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>FDTD 不替代胶随机，不算全芯片。材料 \\(n,k\\) 测不准时，网格再密也错。不要发明 arXiv 编号或未公开的「比 RCWA 永远准」。</p><p>后课默认：非周期掩模电磁可以用 FDTD 当参考；周期重复结构有更匹配的模态展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FDTD 解掩模 3D 麦克斯韦，服务缺陷、拐角与校准，不服务全芯片迭代。</li><li>通带内的近场才进晶圆；倏逝分量被 NA 丢掉。</li><li>剖面与 \\(n,k\\) 是输入合同。</li><li>出处：Taflove FDTD 传统；掩模 EMF 仿真的公开光刻应用。</li></ul>',5))])}const B=i(p,[["render",E]]);export{F as __pageData,B as default};
